import raw from '../public/timeline.json';
import type {TBeat, Timeline} from './types';
import {clamp} from './lib/easing';

/** Generated by `npm run timeline` (scripts/build-timeline.mjs). */
export const timeline = raw as unknown as Timeline;

export const getBeat = (id: string): TBeat => {
  const b = timeline.beats.find((x) => x.id === id);
  if (!b) throw new Error(`Unknown beat id "${id}"`);
  return b;
};

/** 0..1 progress through (a fraction window of) a beat. */
export const beatProgress = (id: string, t: number, a = 0, b = 1) => {
  const beat = getBeat(id);
  const from = beat.startSec + beat.durSec * a;
  const span = Math.max(1e-6, beat.durSec * (b - a));
  return clamp((t - from) / span);
};

/** Absolute time (seconds) at which word `idx` of beat `id` starts. */
export const wordTime = (id: string, idx: number) => {
  const beat = getBeat(id);
  const w = beat.words[Math.min(idx, beat.words.length - 1)];
  return beat.startSec + (w ? w.s : 0);
};

/** Absolute time of the first spoken word equal to `word` (case/punctuation-insensitive). */
export const whenSaid = (id: string, word: string, occurrence = 1) => {
  const beat = getBeat(id);
  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9']/g, '');
  let n = 0;
  for (let i = 0; i < beat.words.length; i++) {
    if (norm(beat.words[i].w) === norm(word) && ++n === occurrence) {
      return beat.startSec + beat.words[i].s;
    }
  }
  throw new Error(`"${word}" (#${occurrence}) not spoken in beat ${id}`);
};
